#!/usr/bin/env node
// Generates src/generated/abis.ts from the ABIs committed in packages/contracts/abi (D5).
// No forge needed here: CI checks abi/ against `forge inspect` in the contracts job, and checks this output
// against abi/ in the shared job. Never edit the generated file by hand.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const abiDir = join(here, '../../contracts/abi');
const outFile = join(here, '../src/generated/abis.ts');

const files = readdirSync(abiDir)
  .filter((f) => f.endsWith('.json'))
  .sort();

let out = `// GENERATED by scripts/gen-abis.mjs from packages/contracts/abi. Do not edit.\n`;
for (const file of files) {
  const name = file.replace(/\.json$/, '');
  const abi = JSON.parse(readFileSync(join(abiDir, file), 'utf8'));
  const constName = `${name.replace(/^./, (c) => c.toLowerCase())}Abi`;
  out += `\nexport const ${constName} = ${JSON.stringify(abi, null, 2)} as const;\n`;
}
writeFileSync(outFile, out);
console.log(`generated ${files.length} ABIs -> src/generated/abis.ts`);
